import base64
import hashlib
import hmac
import json


def b64(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode()


def unb64(text: str) -> bytes:
    return base64.urlsafe_b64decode(text + "=" * (-len(text) % 4))


def sign(text: str, secret: str) -> str:
    return b64(hmac.new(secret.encode(), text.encode(), hashlib.sha256).digest())


def make_token(payload: dict, secret: str) -> str:
    header = b64(json.dumps({"alg": "HS256", "typ": "JWT"}, separators=(",", ":")).encode())
    body = b64(json.dumps(payload, separators=(",", ":")).encode())
    return header + "." + body + "." + sign(header + "." + body, secret)


def read_token(token: str, secret: str, now: int):
    parts = token.split(".")
    if len(parts) != 3:
        return None
    if not hmac.compare_digest(parts[2].encode(), sign(parts[0] + "." + parts[1], secret).encode()):
        return None
    payload = json.loads(unb64(parts[1]))
    if payload.get("exp", 0) < now:
        return None
    return payload


SECRET = "lesson-secret"
token = make_token({"sub": "anna", "exp": 100}, SECRET)
print(token.count("."))
print(read_token(token, SECRET, 50))
print(read_token(token, SECRET, 150))
print(read_token(token + "x", SECRET, 50))
print(read_token(token, "other", 50))

import base64
import hashlib
import hmac
import json
import time

from fastapi import Depends, FastAPI, Header, HTTPException
from fastapi.testclient import TestClient

SECRET = "lesson-secret"


def b64(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode()


def unb64(text: str) -> bytes:
    return base64.urlsafe_b64decode(text + "=" * (-len(text) % 4))


def sign(text: str, secret: str) -> str:
    return b64(hmac.new(secret.encode(), text.encode(), hashlib.sha256).digest())


def make_token(payload: dict, secret: str) -> str:
    header = b64(json.dumps({"alg": "HS256", "typ": "JWT"}, separators=(",", ":")).encode())
    body = b64(json.dumps(payload, separators=(",", ":")).encode())
    return header + "." + body + "." + sign(header + "." + body, secret)


def read_token(token: str, secret: str, now: int):
    parts = token.split(".")
    if len(parts) != 3:
        return None
    if not hmac.compare_digest(parts[2].encode(), sign(parts[0] + "." + parts[1], secret).encode()):
        return None
    payload = json.loads(unb64(parts[1]))
    if payload.get("exp", 0) < now:
        return None
    return payload


app = FastAPI()


def current_user(authorization: str = Header(None)) -> dict:
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Нужен токен")
    payload = read_token(authorization[7:], SECRET, int(time.time()))
    if payload is None:
        raise HTTPException(status_code=401, detail="Неверный токен")
    return payload


@app.get("/me")
def me(user: dict = Depends(current_user)):
    return {"user": user["sub"]}


client = TestClient(app)
token = make_token({"sub": "anna", "exp": 9999999999}, SECRET)
print(client.get("/me").status_code)
print(client.get("/me", headers={"Authorization": "Bearer " + token}).json())
print(client.get("/me", headers={"Authorization": "Bearer abc"}).json())

def require_admin(user: dict = Depends(current_user)) -> dict:
    if user.get("role") != "admin":
        raise HTTPException(status_code=403, detail="Недостаточно прав")
    return user


@app.get("/admin")
def admin_panel(user: dict = Depends(require_admin)):
    return {"hello": user["sub"]}


